mapper.select:
/*getPrDetail*/ SELECT A.DESCRIPTION ||' '||A.SPECIFICATION ITEM_INFO , (SELECT C.USER_NAME_LOC FROM ICOMLUSR C WHERE C.COM_CODE=B.COMPANY_CODE AND C.LEGACY_USER_ID=B.TEXT3 AND ROWNUM=1 ) AS S_USER_NM , A.ADD_USER_TEL S_USER_TEL , B.TEXT3 , A.DESCRIPTION , A.SPECIFICATION , A.TARGET_QTY , A.RETURN_REASON , DECODE(A.RECV_FLAG, 'AT', 'I/F','GA','발주대기','PT','발주대기','GR','결재반려','GS','결재중','PS','결재중','PA','일반승인','PC','발주시','RR','반려','PR','반려','TS','임시저장','GD','상신취소','PD','상신취소') RECV_FLAG , A.REMARK , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE LEGACY_USER_ID = A.REQ_USER_ID AND ROWNUM = 1) REQ_USER_NAME , UNIT_MEASURE , a.ref_pr_no , a.buyer_item_no FROM ICOMPRDT A, ICOMCOD2 B WHERE 1=1 AND A.STATUS <> 'D' AND A.BUYER= B.COMPANY_CODE AND A.ADD_USER_DEPT = B.CODE AND B.TYPE='C001' AND a.BUYER = #{BUYER } AND a.PR_NO = #{PR_NO }
AND a.BUYER_ITEM_NO = #{BUYER_ITEM_NO }
AND ROWNUM = 1

/*getGiReqExcelList*/ SELECT A.ERSDA , A.I_MBLNR , A.STEXT , A.ENAME , A.MATNR , A.MAKTX , A.GIMENGE , A.GIMENGE GIMENGE2 , A.POST_CODE1 , A.CITY1 , A.STREET , A.TEL_NUMBER , (SELECT SPECIFICATION FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.MATNR)SPECIFICATION , A.MEINS , A.ERNAM , ROWNUM SEQ , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID =B.REQ_USER_ID) DAESG_NM FROM EAI.IF_COWAY_PR_SEND A , ICOMPRDT B WHERE A.BUYER = B.BUYER AND A.PR_NO = B.PR_NO AND A.PR_SEQ = B.PR_SEQ AND ( A.BUYER , A.PR_NO , A.PR_SEQ ) IN (
(#{item.BUYER }, #{item.PR_NO }, #{item.PR_SEQ })
)

/*getPassUserInfo*/ SELECT B.PASS_TP , USER_NAME_LOC , MOBILE_PHONE , EMAIL , PASS_DATE , NVL((SELECT TEXT1 FROM ICOMCOD2 WHERE CODE = C.POSITION AND TYPE = 'C003' AND COMPANY_CODE = C.COM_CODE), '기타') POSITION , PASS_ADD , DECODE(B.PASS_TP, 0, '기안', 1, '승인', 2, '참조', 3, '반려', 4, '상신취소', 9, '임시저장')PASS_TP_NAME FROM ICOMTRGW A , ICOGPASSLN B , ICOMLUSR C WHERE A.COM_CODE = B.COMPANY AND B.COMPANY = #{BUYER } AND A.TARGET = B.DOCU_NO AND A.DOC_NAME = 'PR' AND A.KEY_1 = #{PR_NO } AND C.USER_ID = B.USER_ID
AND B.PASS_TP = #{PASS_TP }
ORDER BY TO_NUMBER(ORDER_NO)

/*buyer.mdam.selectGsysDeliveryDisplaySum*/ SELECT A.* FROM ( SELECT A.SCREEN_ID, A.USER_ID, A.MBLNR, A.MATNR, A.ORGEH, A.STEXT, A.POST_CODE1, A.CITY1, A.STREET, A.TEL_NUMBER, A.MOB_NUMBER, A.LAEDA, A.RQMENGE, A.RQCMENGE, (SELECT MAX(B.DESCRIPTION_LOC) FROM ICOMBYIT B WHERE 1 = 1 AND B.BUYER IN ('KRCOWA0002', 'KRCOWA0003', 'KRCOWA0007', 'KRCOWA0008') AND B.BUYER_ITEM_NO = TO_CHAR(TO_NUMBER(A.MATNR)) ) AS S_ITEM_NM, D.USER_NAME_LOC AS S_USER_NM, CASE WHEN E.ADD_USER_TEL IS NOT NULL THEN E.ADD_USER_TEL ELSE D.PHONE_NUMBER END AS S_USER_TEL FROM COWAY_ZMM_GSYS_DE_RER_DISPLAY A , ICOMCOD2 C , ICOMLUSR D , ICOMPRDT E WHERE 1 = 1 AND A.SCREEN_ID = #{st_screen_id} AND A.USER_ID = #{st_user_id}
AND C.TYPE = 'C001' AND C.CODE = A.ORGEH AND C.COMPANY_CODE = 'KRCOWA0001'
AND D.COM_CODE = C.COMPANY_CODE AND D.LEGACY_USER_ID = C.TEXT3
AND A.BUYER = E.BUYER(+) AND A.PR_NO = E.PR_NO(+) AND A.PR_SEQ = E.PR_SEQ(+)
ORDER BY A.MBLNR, A.MATNR ) A

/*buyer.mdam.selectGsysDeliveryDisplay*/
SELECT A.SCREEN_ID, A.USER_ID, A.MBLNR, A.MATNR, A.ORGEH, A.STEXT, A.POST_CODE1, A.CITY1, A.STREET, A.TEL_NUMBER, A.MOB_NUMBER, A.BUYER, A.PR_NO, A.PR_SEQ, SUBSTR(A.MBLNR,1,2) AS MBLNR_PREFIX, A.ERSDA, A.ENAME FROM COWAY_ZMM_GSYS_DE_RER_DISPLAY A , ICOMCOD2 C , ICOMLUSR D WHERE 1 = 1
AND A.SCREEN_ID = #{st_screen_id} AND A.USER_ID = #{st_user_id}
AND C.TYPE = 'C001' AND C.CODE = A.ORGEH AND C.COMPANY_CODE = 'KRCOWA0001'
AND D.COM_CODE = C.COMPANY_CODE AND D.LEGACY_USER_ID = C.TEXT3 ORDER BY MBLNR, MATNR

mapper.delete:
/*buyer.mdam.deleteGsysDeliveryDisplaySum*/
DELETE FROM COWAY_ZMM_GSYS_DE_RER_DISPLAY
 WHERE 1 = 1
   AND SCREEN_ID = #{st_screen_id}
   AND USER_ID   = #{st_user_id}

mapper.update:
/*buyer.mdam.insertGsysDeliveryDisplay*/ INSERT ALL
INTO COWAY_ZMM_GSYS_DE_RER_DISPLAY ( SCREEN_ID, USER_ID, MBLNR, MATNR, ORGEH, STEXT, POST_CODE1, CITY1, STREET, TEL_NUMBER, MOB_NUMBER, ERSDA, ENAME ) VALUES ( #{item.SCREEN_ID}, #{item.USER_ID}, #{item.MBLNR}, #{item.MATNR}, #{item.ORGEH}, #{item.STEXT}, #{item.POST_CODE1}, #{item.CITY1}, #{item.STREET}, #{item.TEL_NUMBER}, #{item.MOB_NUMBER}, #{item.ERSDA}, #{item.ENAME} )
SELECT * FROM DUAL

/*buyer.mdam.insertGsysDeliveryDisplaySumBatch*/ INSERT ALL
INTO COWAY_ZMM_GSYS_DE_RER_DISPLAY ( SCREEN_ID, USER_ID, MBLNR, MATNR, ORGEH, STEXT, MAKTX, GIMENGE, RQMENGE, RQCMENGE, SPEME, MEINS, BUKRS, LAEDA, MOB_NUMBER, POST_CODE1, CITY1, STREET, TEL_NUMBER ) VALUES ( #{item.SCREEN_ID}, #{item.USER_ID}, #{item.MBLNR}, #{item.MATNR}, #{item.ORGEH}, #{item.STEXT}, #{item.MAKTX}, trim(#{item.GIMENGE}),trim(#{item.RQMENGE}), trim(#{item.RQCMENGE}),trim(#{item.SPEME}), #{item.MEINS}, #{item.BUKRS}, #{item.LAEDA}, #{item.MOB_NUMBER}, #{item.POST_CODE1}, #{item.CITY1}, #{item.STREET}, #{item.TEL_NUMBER} )
SELECT * FROM DUAL

/* buyer.mdam.updateGsysExcelInfo */
UPDATE COWAY_ZMM_GSYS_DE_RER_DISPLAY
   SET STEXT      = #{STEXT}
     , MAKTX      = #{MAKTX}
     , GIMENGE    = trim(#{GIMENGE})
     , RQMENGE    = trim(#{RQMENGE})
     , RQCMENGE   = trim(#{RQCMENGE})
     , SPEME      = trim(#{SPEME})
     , MEINS      = #{MEINS}
     , BUKRS      = #{BUKRS}
     , LAEDA      = #{LAEDA}
     , MOB_NUMBER = #{MOB_NUMBER}
     , POST_CODE1 = #{POST_CODE1}
     , CITY1      = #{CITY1}
     , STREET     = #{STREET}
     , TEL_NUMBER = #{TEL_NUMBER}
 WHERE 1 = 1
   AND SCREEN_ID = #{SCREEN_ID}
   AND USER_ID   = #{USER_ID}
   AND MBLNR     = #{MBLNR}
   AND MATNR     = #{MATNR}
   AND ORGEH     = #{ORGEH}
